head.b:skin:
/*
 * Theme: Blogger Ve Tinh Chuan SEO - Dong Bo Thuong Hieu
 * Designed for: Môi Trường Đô Thị Số 1 Quảng Ninh (thongtaccongquangninh.com)
 * Designed by: Antigravity
 */

/* Reset CSS */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Outfit', sans-serif;
  background-color: #f4f6f9;
  color: #1f2937;
  line-height: 1.6;
  font-size: 16px;
}
a { color: #1890ff; text-decoration: none; transition: all 0.3s ease; }
a:hover { color: #096dd9; text-decoration: underline; }
img { max-width: 100%; height: auto; display: block; }

/* Layout Containers */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Header - Dong bo mau xanh duong thongtaccongquangninh.com */
header {
  background: #003a8c;
  color: white;
  padding: 15px 0;
  box-shadow: 0 4px 10px rgba(0,0,0,0.1);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-wrapper {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.logo h1 {
  font-size: 24px;
  font-weight: 800;
}
.logo h1 a {
  color: white;
}
.logo h1 a:hover {
  text-decoration: none;
}

/* Hotline nhap nhay o Header */
.header-hotline {
  background: #ff4d4f;
  padding: 10px 20px;
  border-radius: 50px;
  font-weight: 700;
  font-size: 16px;
  box-shadow: 0 4px 15px rgba(255, 77, 79, 0.4);
  animation: pulse 1.5s infinite;
}
.header-hotline a {
  color: white;
}
@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}

/* Main Content Area */
.main-wrapper {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 30px;
  margin: 40px auto;
}

/* Post Area */
.post-card {
  background: white;
  padding: 30px;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
  margin-bottom: 30px;
}
.post-title {
  font-size: 28px;
  font-weight: 700;
  color: #003a8c;
  margin-bottom: 15px;
  line-height: 1.3;
}
.post-meta {
  font-size: 14px;
  color: #6b7280;
  margin-bottom: 25px;
}
.post-body {
  font-size: 16px;
  color: #374151;
  text-align: justify;
}
.post-body h2 {
  font-size: 22px;
  color: #003a8c;
  margin: 30px 0 15px 0;
  border-left: 5px solid #1890ff;
  padding-left: 15px;
}
.post-body h3 {
  font-size: 18px;
  color: #003a8c;
  margin: 20px 0 10px 0;
}
.post-body p {
  margin-bottom: 15px;
}
.post-body ul, .post-body ol {
  margin-bottom: 20px;
  padding-left: 20px;
}
.post-body li {
  margin-bottom: 8px;
}

/* Sidebar */
aside {
  display: flex;
  flex-direction: column;
  gap: 30px;
}
.widget-box {
  background: white;
  padding: 25px;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
}
.widget-title {
  font-size: 18px;
  font-weight: 700;
  color: #003a8c;
  border-bottom: 2px solid #f0f0f0;
  padding-bottom: 12px;
  margin-bottom: 15px;
}

/* Widget NAP lien he giong thongtaccongquangninh.com */
.nap-box {
  background: linear-gradient(135deg, #003a8c 0%, #1890ff 100%);
  color: white;
  padding: 25px;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(24, 144, 255, 0.3);
}
.nap-box h3 {
  font-size: 18px;
  font-weight: 800;
  margin-bottom: 15px;
  border-bottom: 1px solid rgba(255,255,255,0.2);
  padding-bottom: 10px;
}
.nap-box p {
  font-size: 14px;
  margin-bottom: 12px;
  line-height: 1.5;
}
.nap-btn {
  display: block;
  background: #ff4d4f;
  color: white !important;
  text-align: center;
  padding: 12px;
  border-radius: 8px;
  font-weight: 700;
  margin-top: 15px;
  box-shadow: 0 4px 10px rgba(255, 77, 79, 0.3);
  text-decoration: none !important;
}

/* Footer */
footer {
  background: #001529;
  color: #8c9ba5;
  padding: 40px 0;
  text-align: center;
  font-size: 14px;
  border-top: 5px solid #003a8c;
}
footer p {
  margin-bottom: 10px;
}
footer a {
  color: white;
  font-weight: 600;
}

/* Responsive */
@media (max-width: 768px) {
  .main-wrapper {
    grid-template-columns: 1fr;
  }
  .header-wrapper {
    flex-direction: column;
    gap: 15px;
    text-align: center;
  }
}
